import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadMenalData(){const e=readFileSync(resolve(__dirname,"../../menal-falls-explorer/menal-data.js"),"utf-8");return new Function(e+"\nreturn { MENAL_INFO, NATURE_HERITAGE_SPOTS, SEASONAL_DATA, NEARBY_ATTRACTIONS, GALLERY_IMAGES, REFERENCES };")()}describe("Menal Falls Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadMenalData()}),describe("MENAL_INFO metadata",()=>{it("contains correct Menal Falls location, height, and heritage dynasty",()=>{expect(e.MENAL_INFO.id).toBe("menal-falls"),expect(e.MENAL_INFO.title).toContain("Menal Falls"),expect(e.MENAL_INFO.waterfallHeight).toContain("45 Meters"),expect(e.MENAL_INFO.heritageDynasty).toContain("Chahamana")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.MENAL_INFO.quickStats)).toBe(!0),expect(e.MENAL_INFO.quickStats.length).toBe(6)})}),describe("NATURE_HERITAGE_SPOTS & SEASONAL_DATA",()=>{it("contains nature and heritage spots connecting waterfall and temples",()=>{expect(Array.isArray(e.NATURE_HERITAGE_SPOTS)).toBe(!0),expect(e.NATURE_HERITAGE_SPOTS.length).toBeGreaterThanOrEqual(4);const t=e.NATURE_HERITAGE_SPOTS.find(e=>"mahanaleshwar-temple"===e.id);expect(t).toBeDefined(),expect(t.category).toBe("Heritage Site"),expect(Array.isArray(e.SEASONAL_DATA)).toBe(!0),expect(e.SEASONAL_DATA.length).toBeGreaterThanOrEqual(3)})}),describe("NEARBY_ATTRACTIONS & REFERENCES",()=>{it("contains nearby attractions and references",()=>{expect(Array.isArray(e.NEARBY_ATTRACTIONS)).toBe(!0),expect(e.NEARBY_ATTRACTIONS.length).toBeGreaterThanOrEqual(4),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});